window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8abe2bf51fade142"]={"versions": [{"id": "FIG-8abe2bf51fade142", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Profildefinition zur Definition der AUTOSAR-Vorlagenstereotypen für Typen und Prototypen im AUTOSAR-Template-Modeling-Umfeld. Das Diagramm spezifiziert die Vererbungshierarchie der AUTOSAR-Profil-Stereotypen ausgehend von der UML-Superstruktur-Metaklasse <code>Kernel::Class</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kernel::Class</strong>: Abstrakte Metaklasse des UML-Metamodells (<code>Classifier / «metaclass» Kernel::Class</code>).\n</li><li><strong>atpClass</strong>: Stereotyp, erweitert <code>Kernel::Class</code> über eine erforderliche Erweiterungsbeziehung (<code>«extends» {required}</code>).\n</li><li><strong>atpIdentifiable</strong>: Stereotyp, spezialisiert <code>atpClass</code>.\n</li><li><strong>atpStructured</strong>: Abstrakter Stereotyp (kursiv gesetzt), spezialisiert <code>atpIdentifiable</code>.\n</li><li><strong>atpStructuringFeature</strong>: Abstrakter Stereotyp (kursiv gesetzt), spezialisiert <code>atpIdentifiable</code>.\n</li><li><strong>atpType</strong>: Konkreter Stereotyp, spezialisiert <code>atpStructured</code>.\n</li><li><strong>atpStructureElement</strong>: Konkreter Stereotyp, Mehrfachvererbung (spezialisiert sowohl <code>atpStructured</code> als auch <code>atpStructuringFeature</code>).\n</li><li><strong>atpPrototype</strong>: Konkreter Stereotyp, spezialisiert <code>atpStructuringFeature</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Sequenzabläufe, Nachrichtenflüsse oder Zustandsübergänge.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert normative Stereotypen des AUTOSAR-Profils für Metamodell-Elemente. Klassen, die als Typ (<code>atpType</code>) fungieren, müssen die Merkmale von <code>atpStructured</code> erfüllen. Prototypen (<code>atpPrototype</code>) bilden Strukturierungsmerkmale (<code>atpStructuringFeature</code>). Elemente mit Doppelnatur (<code>atpStructureElement</code>) vereinen beide Aspekte. Alle Stereotypen basieren transitiv auf <code>atpClass</code> und erweitern <code>Kernel::Class</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-afe0f19eb196d569", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Profildefinition zur Spezifikation der Stereotypenhierarchie für Typen und Prototypen innerhalb der AUTOSAR-Vorlagenmodellierung. Das Diagramm definiert die Vererbungsbeziehungen der AUTOSAR-Profilstereotypen mit <code>atpClass</code> als gemeinsamer Basis.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>atpClass</strong>: Basis-Stereotyp an der Spitze der dargestellten Vererbungshierarchie.\n</li><li><strong>atpStructured</strong>: Abstrakter Stereotyp (kursiv gesetzt), spezialisiert <code>atpClass</code>.\n</li><li><strong>atpStructuringFeature</strong>: Abstrakter Stereotyp (kursiv gesetzt), spezialisiert <code>atpClass</code>.\n</li><li><strong>atpType</strong>: Konkreter Stereotyp, spezialisiert <code>atpStructured</code>.\n</li><li><strong>atpStructuredElement</strong>: Konkreter Stereotyp mit Mehrfachvererbung, spezialisiert sowohl <code>atpStructured</code> als auch <code>atpStructuringFeature</code>.\n</li><li><strong>atpPrototype</strong>: Konkreter Stereotyp, spezialisiert <code>atpStructuringFeature</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Sequenzabläufe, Nachrichtenflüsse oder Zustandsübergänge.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert normative Stereotypen des AUTOSAR-Profils für Modellierungsentitäten. Modellierungselemente mit Typcharakter erben von <code>atpStructured</code>, Ausprägungsmerkmale von <code>atpStructuringFeature</code>. Strukturierte Elemente (<code>atpStructuredElement</code>) kombinieren beide Rollen über Mehrfachvererbung. <code>atpClass</code> fungiert als oberster Generalisierungsanker für diese Strukturkonzepte.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-27669da866010436", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Profildefinition zur Spezifikation der Stereotypenhierarchie für Typen und Prototypen innerhalb der AUTOSAR-Vorlagenmodellierung. Das Diagramm definiert die Vererbungsbeziehungen der AUTOSAR-Profilstereotypen mit <code>atpClass</code> als gemeinsamer Basis.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>atpClass</strong>: Basis-Stereotyp an der Spitze der dargestellten Vererbungshierarchie.\n</li><li><strong>atpStructured</strong>: Abstrakter Stereotyp (kursiv gesetzt), spezialisiert <code>atpClass</code>.\n</li><li><strong>atpStructuringFeature</strong>: Abstrakter Stereotyp (kursiv gesetzt), spezialisiert <code>atpClass</code>.\n</li><li><strong>atpType</strong>: Konkreter Stereotyp, spezialisiert <code>atpStructured</code>.\n</li><li><strong>atpStructuredElement</strong>: Konkreter Stereotyp mit Mehrfachvererbung, spezialisiert sowohl <code>atpStructured</code> als auch <code>atpStructuringFeature</code>.\n</li><li><strong>atpPrototype</strong>: Konkreter Stereotyp, spezialisiert <code>atpStructuringFeature</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Sequenzabläufe, Nachrichtenflüsse oder Zustandsübergänge.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert normative Stereotypen des AUTOSAR-Profils für Modellierungsentitäten. Modellierungselemente mit Typcharakter erben von <code>atpStructured</code>, Ausprägungsmerkmale von <code>atpStructuringFeature</code>. Strukturierte Elemente (<code>atpStructuredElement</code>) kombinieren beide Rollen über Mehrfachvererbung. <code>atpClass</code> fungiert als oberster Generalisierungsanker für diese Strukturkonzepte.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8abe2bf51fade142", "to": "FIG-afe0f19eb196d569", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Kernel::Class &amp; «extends»</strong>: Die Metaklasse <code>Classifier / «metaclass» Kernel::Class</code> und die Erweiterungsbeziehung <code>«extends» {required}</code> von <code>atpClass</code> wurden entfernt.\n</li><li><strong>atpIdentifiable</strong>: Der Stereotyp <code>atpIdentifiable</code> in der Vererbungshierarchie zwischen <code>atpClass</code> und <code>atpStructured</code>/<code>atpStructuringFeature</code> wurde entfernt; <code>atpStructured</code> und <code>atpStructuringFeature</code> erben direkt von <code>atpClass</code>.\n</li><li><strong>atpStructureElement / atpStructuredElement</strong>: Die Benennung des Stereotyps wurde von <code>atpStructureElement</code> zu <code>atpStructuredElement</code> korrigiert.\n</li></ul>"}, {"from": "FIG-afe0f19eb196d569", "to": "FIG-27669da866010436", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
